(7459922, 1182473, 170281, '<td valign="top">Excellent.  Creative and perfectly within the spirit of the challenge.  Nicely done.</td>', 'Excellent.  Creative and perfectly within the spirit of the challenge.  Nicely done.', '2016-06-12 19:23:01.000000', NULL, 1),
(7459923, 1182531, 170281, '<td valign="top">I am not a big fan of the subject matter, but I love how you captured the essence of the challenge in this unique array of the cool colors.</td>', 'I am not a big fan of the subject matter, but I love how you captured the essence of the challenge in this unique array of the cool colors.', '2016-06-12 19:24:32.000000', NULL, 1),
(7459924, 1182365, 170281, '<td valign="top">Simple, creative and well-composed.  Nice!</td>', 'Simple, creative and well-composed.  Nice!', '2016-06-12 19:26:28.000000', NULL, 1),
(7459925, 1182270, 170281, '<td valign="top">This would have been interesting to see in the Surreal and Dreamy challenge.</td>', 'This would have been interesting to see in the Surreal and Dreamy challenge.', '2016-06-12 19:27:45.000000', NULL, 1),
(7459926, 1182310, 170281, '<td valign="top">I really like the image, but the red and yellow (hot colors) captures you attention versus the soft blues and purples.</td>', 'I really like the image, but the red and yellow (hot colors) captures you attention versus the soft blues and purples.', '2016-06-12 19:29:14.000000', NULL, 1),
(7459928, 1182552, 170281, '<td valign="top">I like the simplicity and capture of the cool colors.  I think it would have been a bit more interesting if you followed the rule of thirds and place the center of the umbrella at one of the intersects.</td>', 'I like the simplicity and capture of the cool colors.  I think it would have been a bit more interesting if you followed the rule of thirds and place the center of the umbrella at one of the intersects.', '2016-06-12 19:30:58.000000', NULL, 1),
(7459930, 1182549, 170281, '<td valign="top">As I mentioned to one of the other photographers, I like the capture of the cool blues and purples, but the center of focus is on the pig which is in the hot colors of orange and yellow.</td>', 'As I mentioned to one of the other photographers, I like the capture of the cool blues and purples, but the center of focus is on the pig which is in the hot colors of orange and yellow.', '2016-06-12 19:33:45.000000', NULL, 1),
(7459931, 1182585, 170281, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2016-06-12 19:41:01.000000', NULL, 1),
